authRouter.post('/init-oidc-login', validateBody(initOidcLoginBodySchema), initOidcLoginController);

authRouter.post('/complete-oidc-login', validateBody(completeOidcLoginBodySchema), completeOidcLoginController);

authRouter.post('/test-email-login', validateBody(testEmailLoginBodySchema), testEmailLoginController);

authRouter.post(
	'/init-email-login',
	otpRequestRateLimiter,
	validateBody(initEmailLoginBodySchema),
	initEmailLoginController,
);

authRouter.post(
	'/complete-email-login',
	otpVerifyRateLimiter,
	validateBody(completeEmailLoginBodySchema),
	completeEmailLoginController,
);

authRouter.post(
	'/verify-session',
	authMiddleware({
		allowTeacher: { allowedRoles: ['admin', 'teacher', 'data_protection_officer'], sessionRequired: true },
		allowStudent: { sessionRequired: true },
	}),
	verifySessionController,
);

authRouter.post(
	'/logout',
	authMiddleware({
		allowTeacher: { allowedRoles: ['admin', 'teacher', 'data_protection_officer'], sessionRequired: false },
		allowStudent: { sessionRequired: false },
	}),
	logoutController,
);

// Mints a session for an arbitrary user given only the super-admin API key, so
// it is never registered in production: a leaked key would otherwise be a full
// account takeover across every school. Unregistered means a plain 404 rather
// than a 401, which also keeps the endpoint out of production route probes.
if (ENVIRONMENT !== 'production') {
	authRouter.post(
		'/debug-login',
		authMiddleware({ allowSuperAdmin: true }),
		validateBody(debugLoginBodySchema),
		debugLoginController,
	);
}
